// A review or occasion switch must never silently use an older valid amount.
function guardPending(e){if(view==='options'&&responseOptionId&&e.target.closest('[data-recovery-cancel-response]'))return;if(e.target.closest('#money-cancel,#money-cancel-review'))return;if(e.target.closest('#backup-prepare,#backup-confirm')&&moneyEditor){e.preventDefault();e.stopImmediatePropagation();message('Apply or cancel the pending money edit before exporting.');return;}if(e.target.closest('[data-quantity-discard]'))return;if(e.target.closest('#backup-prepare,#backup-confirm')&&reconcileQuantityDrafts()){e.preventDefault();e.stopImmediatePropagation();message('Update or discard pending quantity inputs in Quantities & logistics before exporting.');return;}if(e.type==='click'&&!e.target.closest('button'))return;if(e.target.closest('#response-cancel'))return;if(e.target.closest('#backup-cancel,#backup-cancel-read'))return;const retentionAction=e.target.closest('[data-retain]')?.dataset.retain;if(['off','discard','check','restore'].includes(retentionAction))return;for(const el of document.querySelectorAll('#panel input[type="number"],#panel input[type="date"],#panel input[type="time"]')){if(el.closest('#research-manual-form'))continue;try{if(!el.validity.valid)throw Error('Please correct the highlighted amount, date or time before continuing.');if(el.type==='number')money(el.value);}catch(error){e.preventDefault();e.stopImmediatePropagation();el.focus();message(error.message);return;}}}
document.addEventListener('click',guardPending,true);document.addEventListener('submit',guardPending,true);

let retention=null,remember=false,expectedRevision=null,pending=null,retentionBusy=false,retentionMessage='Session-only by default. Nothing is saved automatically.';
try{retention=createRetention({storage:window.localStorage,locks:navigator.locks,newRevision:()=>crypto.randomUUID()});pending=retention.inspect();}catch(error){retentionMessage=error.message;}
function retentionRender(){
 const hasStored=pending?.raw!==null&&pending?.raw!==undefined;
 $('#retention-panel').innerHTML=`<h2>Your local draft choice</h2><p><strong>${remember?'Remembering enabled — manual Save only.':'Session-only mode.'}</strong> This prototype never saves automatically. Local storage is on this browser/profile only, not encrypted by this app, and may be visible to others who use it. Browser clearing, private mode, quota or device loss can remove it. No sync or guaranteed retention.</p><p role="status" aria-live="polite">${esc(retentionMessage)}</p>${hasStored?`<div class="summary"><strong>${pending.error?'Unreadable or unsupported stored draft':'A stored draft is available'}</strong><p>${pending.error?'It was not loaded or overwritten. You may discard exactly the inspected stored copy.':`Contains ${pending.snapshot.data.occasions.length} occasion(s). It has not been loaded into this session.`}</p>${pending.snapshot?'<button data-retain="restore">Restore stored draft & enable remembering (replace this session)</button> ':''}<button data-retain="discard">Discard this stored draft from this browser</button><p class="small">Restoring replaces this session’s edits. Discarding removes the stored copy, not your current session. Check before choosing.</p></div>`:''}<div class="actions">${remember?'<button data-retain="save" class="primary">Save current draft on this browser</button>':(!hasStored?'<button data-retain="enable">Enable remembering & save current draft</button>':'')} ${remember||expectedRevision!==null?'<button data-retain="off">Remember OFF & clear stored copy</button>':''} <button data-retain="check">Check for stored draft</button></div><p class="small">Use aliases and leave sensitive details out. No invitations, contact transfer, cloud backup or account is involved. Other tabs may still hold their own session copies after clearing.</p>`;
 for(const b of document.querySelectorAll('[data-retain]'))b.disabled=retentionBusy||!retention;
 $('#session-notice').innerHTML=`<strong>${remember?'Local remembering enabled — manual Save required.':'Session-only by default — unsaved changes are lost on refresh or close.'}</strong> Aliases are enough; leave sensitive details out. No accounts, invitations, hosted RSVP or live collaboration. Check what is stored before leaving; retention is not guaranteed.`;
}
async function retentionAction(action){if(retentionBusy||!retention)return;backupUI?.invalidate();retentionBusy=true;retentionRender();try{
 if(action==='check'){pending=retention.inspect();if(pending.raw===null){expectedRevision=null;remember=false;dirty=true;}retentionMessage=pending.raw===null?'No stored draft found. Current session is unchanged.':'Stored draft checked. Current session is unchanged; choose Restore or Discard explicitly.';}
 if(action==='restore'){alternativeSelection=null;alternativeReview=null;manualDraft=null;manualPackageId=null;if(!pending?.snapshot)throw Error('No valid stored draft selected.');const latest=retention.inspect();if(latest.raw!==pending.raw){pending=latest;throw Error('Stored draft changed since you checked. Review the latest copy before restoring.');}guestReview=null;helperReview=null;optionReview=null;journeyProposal=null;requestDraft=null;evidenceReview=null;enquiryPacket=null;enquiryFileReview=null;responseOptionId=null;responseReview=null;responseDraft=null;moneyEditor=null;moneyReview=null;quantityDrafts.clear();occasions=structuredClone(pending.snapshot.data.occasions);active=pending.snapshot.data.active;expectedRevision=pending.snapshot.revision;remember=true;serial=1;editVersion++;dirty=false;pending=null;view='edit';render();focusHeading();retentionMessage='Stored draft restored. Remembering is enabled; further edits require manual Save.';}
 if(action==='enable'||action==='save'){if(moneyEditor)throw Error('Apply or cancel the pending money edit before saving.');if(reconcileQuantityDrafts())throw Error('Update or discard pending quantity inputs in Quantities & logistics before saving.');const captured=editVersion;const saved=await retention.save({occasions,active},expectedRevision);expectedRevision=saved.revision;remember=true;pending=null;dirty=editVersion!==captured;retentionMessage=dirty?'Earlier state saved and read back; newer session changes still need Save.':'Draft saved and read back on this browser. This is not a guarantee against later browser/device loss.';}
 if(action==='off'){remember=false;dirty=true;await retention.clear(expectedRevision);expectedRevision=null;pending=null;dirty=true;retentionMessage='Remember OFF. Stored copy removed and absence verified. Your current plan remains in this session only; other open tabs may retain their session copies.';}
 if(action==='discard'){if(!pending)throw Error('Check the stored draft first.');remember=false;dirty=true;await retention.clearInspected(pending.raw);pending=null;expectedRevision=null;remember=false;dirty=true;retentionMessage='Inspected stored draft removed and absence verified. Current session is unchanged and not saved.';}
 }catch(error){retentionMessage=error.message;if(action==='off'||action==='discard')retentionMessage+=' Clearing was not confirmed; stored details may remain. Keep this session open: your current plan is not confirmed saved. Review a portable backup to preserve it, or check the stored draft before retrying.';}finally{retentionBusy=false;retentionRender();}}
$('#retention-panel').addEventListener('click',e=>{const b=e.target.closest('[data-retain]');if(b)retentionAction(b.dataset.retain);});
window.addEventListener('storage',e=>{if(e.key===null||e.key==='family-occasions.private-draft.v1'){dirty=true;retentionMessage='Another tab changed or cleared the stored draft. Current session is unchanged. Check it before saving; stale writes will be blocked.';retentionRender();}});
retentionRender();

function renderGuest(o){
 if(guestReview&&!guestReviewCurrent(o,guestReview))guestReview=null;helperReview=null;optionReview=null;journeyProposal=null;
 if(!guestReview){$('#panel').innerHTML=`<section class="card"><p class="eyebrow">FOR YOUR GUESTS · MANUAL SHARING ONLY</p><h2>A practical copy, not your private plan</h2><p>Choose gatherings and review the exact information before printing or sharing yourself. Budget, tasks, helper roles, celebration preferences and run-sheet cues are excluded. Gathering names and venues may still contain private details—check them.</p><form id="guestform" class="actions"><label>Guest-copy heading<input name="heading" maxlength="120" value="Gathering details" required></label><fieldset><legend>Which gatherings should appear?</legend>${o.gatherings.map(g=>`<label class="check"><input type="checkbox" name="gathering" value="${esc(g.id)}">${esc(g.title||'Unnamed gathering')} — ${esc(g.date||'date not set')}</label>`).join('')}</fieldset><label class="check"><input type="checkbox" name="practical">Include guest practical notes (check for anything sensitive)</label><p class="small">No gatherings or notes are included until you choose them. People’s names and the organiser’s occasion title are not automatically copied.</p><button class="primary">Prepare guest copy for review</button></form></section>`;return;}
 const c=guestReview.copy;$('#panel').innerHTML=`<div class="printhead"><p class="eyebrow">GUEST PRACTICAL INFORMATION · DRAFT</p><h2>${esc(c.heading)}</h2><p>Details to check before sharing. Not a booking confirmation or invitation delivery.</p></div>${c.gatherings.map(g=>`<section class="card"><h3>${esc(g.name)}</h3><p class="preserve">${esc(g.date||'Date still to confirm')} · ${esc(g.time||'Time still to confirm')} (venue-local time)</p><p class="preserve">${esc(g.venue||'Venue still to confirm')}</p></section>`).join('')}${c.practical?`<section class="card"><h3>Practical information</h3><p class="preserve">${esc(c.practical)}</p></section>`:''}<section class="card actions"><h3>Check this exact copy</h3><p>Only the guest-copy heading, selected gathering names/dates/times/venues and any opted-in practical notes above are included. Check for private addresses or sensitive notes. No RSVP link, email or message is sent. Printing is not a restorable backup.</p><p class="small">Copy prepared: ${esc(guestReview.preparedAt)} (UTC; device clock). This is not a confirmation or a claim that the details were checked at that time.</p><h3>Take this copy away</h3><p>HTML is a standalone, printable handout that opens offline in a browser. Text is a plain-text alternative. Both contain only the selected details above, the preparation time and the same draft/static-copy warnings. No scripts, images, external links or private plan backup are included.</p><p><strong>Before you go:</strong> Later edits do not update these files. Ask the organiser for the latest details. Times are venue-local; timezone not established. Missing details remain unconfirmed. No RSVP, delivery or live updates.</p><label class="check"><input id="guest-file-approved" type="checkbox">I checked these selected details for privacy and missing arrangements; I will open the saved file before sharing it myself.</label><button data-guest-download="html" disabled>Download printable handout (.html)</button> <button data-guest-download="text" disabled>Download plain text (.txt)</button><p id="guest-file-status" role="status">No file saved or sent. After downloading, open the file and check the heading, gatherings and practical notes before sharing.</p><button id="guest-print" class="primary">Print this guest copy</button> <button id="guest-reselect">Change selection</button></section>`;
}

function renderHelper(o){
 if(helperReview&&!helperReviewCurrent(o,helperReview))helperReview=null;
 if(!helperReview){$('#panel').innerHTML=`<section class="card"><p class="eyebrow">HELPERS · MANUAL SHARING ONLY</p><h2>Choose a helper handover</h2><p>Nothing is selected automatically. Select individual tasks and day-of cues, not an alias as a recipient. Duplicate aliases are not unique identities. Owner labels do not mean acceptance or notification.</p><form id="helperform" class="actions"><label>Handover heading<input name="heading" maxlength="120" value="Helper handover" required></label><fieldset><legend>Arrival details to include (names, dates, start times and venues)</legend>${o.gatherings.map(g=>`<label class="check"><input name="logistics" type="checkbox" value="${esc(g.id)}">${esc(g.title||'Unnamed gathering')} — check for private locations</label>`).join('')}</fieldset><label class="check"><input name="practical" type="checkbox">Include existing practical notes / backup arrangements (review sensitive details)</label><fieldset><legend>Tasks to include</legend>${o.tasks.map(t=>`<label class="check"><input name="task" type="checkbox" value="${esc(t.id)}">${esc(t.text||'Unnamed task')} · ${esc(t.owner||'Unassigned')} · ${esc(t.gatheringId?o.gatherings.find(g=>g.id===t.gatheringId)?.title||'Unknown gathering':'Whole occasion')}</label>`).join('')}</fieldset>${o.gatherings.map(g=>`<fieldset><legend>Day-of cues: ${esc(g.title||'Unnamed gathering')}</legend>${g.sequence.map((r,i)=>`<label class="check"><input name="run" type="checkbox" data-gathering="${esc(g.id)}" value="${i}">${esc(r.time||'Time not set')} — ${esc(r.activity||'Activity not set')} · ${esc(r.owner||'Unassigned')}</label>`).join('')}</fieldset>`).join('')}<p>Selected tasks include text, status, owner alias, due date and scope name. Selected cues include gathering name/date, item time, activity and alias. Arrival details and practical notes are included only when separately selected. Budget, preferences, supplier evidence and private roles are excluded. Selected text may itself be private: check the exact copy.</p><button class="primary">Prepare helper handover for review</button></form></section>`+renderHelperResponseSummary(o,esc)+renderHelperCoverage(o,esc);return;}
 const c=helperReview.copy,file=createHelperFile(o,helperReview);$('#panel').innerHTML=`<div class="printhead"><p class="eyebrow">HELPER HANDOVER · DRAFT</p><h2>${esc(c.heading)}</h2><p>For discussion and manual sharing only. Owner aliases are not acceptance or notification; duplicate aliases may refer to different people. Confirm responsibilities privately.</p></div>${c.gatherings?.length?`<section class="card"><h3>Selected arrival details</h3>${c.gatherings.map(g=>`<p class="preserve"><strong>${esc(g.name||'Gathering not set')}</strong><br>${esc(g.date||'Date not set')} · ${esc(g.time||'Start not set')} (venue-local)<br>${esc(g.venue||'Place not set')}</p>`).join('')}</section>`:''}${Object.hasOwn(c,'practical')?`<section class="card"><h3>Selected practical / backup notes</h3><p class="preserve">${esc(c.practical||'No notes entered')}</p></section>`:''}${c.tasks.length?`<section class="card"><h3>Selected tasks</h3><ul>${c.tasks.map(t=>`<li class="preserve"><strong>${esc(t.text||'Task not set')}</strong><br>${t.done?'Done':'To do'} · Owner: ${esc(t.owner||'Unassigned')} · Due: ${esc(t.due||'Not set')} · Scope: ${esc(t.scope||'Unnamed gathering')}</li>`).join('')}</ul></section>`:''}${c.sequence.length?`<section class="card"><h3>Selected day-of cues</h3><ol>${c.sequence.map(r=>`<li class="preserve"><strong>${esc(r.gathering||'Unnamed gathering')}</strong> · ${esc(r.date||'Date not set')} · ${esc(r.time||'Time not set')} (venue-local)<br>${esc(r.activity||'Activity not set')} · Helper: ${esc(r.owner||'Unassigned')}</li>`).join('')}</ol></section>`:''}<section class="card actions"><h3>Review this exact handover</h3><p>Only the selected tasks, cues, arrival details and opted-in practical notes above are included. Check aliases, scope and private surprises before sharing. No delivery, authenticated acceptance tracking or calendar invitation is provided. Printing is not a backup.</p><h3>Exact offline file preview</h3><pre id="helper-file-text" class="preserve">${esc(file.text)}</pre><label class="check"><input id="helper-file-approved" type="checkbox">I checked this exact file for private details and missing arrangements</label><button id="helper-download" disabled>Download this runbook (.txt)</button><p id="helper-file-status" role="status">Nothing downloaded or sent. Earlier copies do not update after edits.</p><button id="helper-print" class="primary">Print this helper handover</button> <button id="helper-reselect">Change selection</button></section>`;
 $('#panel').insertAdjacentHTML('beforeend',renderHelperResponse(o,helperReview,helperResponseReview,esc)+'<section class="card actions"><button type="button" id="helper-coverage-back">Back to task and cue discussions</button><p>Recheck the current organiser records; no readiness or assignment is verified.</p></section>');
}

function choose(label,path,value,choices){return `<label>${esc(label)}<select data-path="${path}">${choices.map(([v,t])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function optionPrice(x){if(x.priceBasis==='unknown')return x.amount===''?'Price unknown':'Incomplete: clear amount or choose estimate/quoted';if(x.amount==='')return 'Incomplete: amount needed';return `${x.priceBasis==='quoted'?'Organiser-recorded quote':'Estimate only'}: ${esc(x.amount)} (currency not specified)`;}
function optionStatus(x){return x.status==='organiser-confirmed'?(x.checkedOn?`Organiser says confirmed, checked ${esc(x.checkedOn)} — not verified by this app`:'Incomplete: confirmation needs a checked date'):x.status==='awaiting'?'Awaiting reply — not confirmed':x.status==='not-available'?'Recorded unavailable':'Researching — not confirmed';}
function renderOptions(o){$('#panel').innerHTML=`<section class="card"><p class="eyebrow">PRIVATE ORGANISER COMPARISON</p><h2>Venues and suppliers, without assumptions</h2><p>Compare possibilities for one gathering at a time. A quote is not a booking; an organiser-recorded confirmation is not verified here. No enquiry, payment or reservation is made. Use fictional names/aliases, not contact or payment details.</p><p>These options stay out of guest and helper copies. They never change the gathering venue. Only an explicit reviewed budget link affects the budget; manual copying could double-count alternatives. Requirements and notes remain private organiser text.</p><button class="primary" data-add="option">Add comparison option</button></section>${renderAlternatives(o,{selection:alternativeSelection,review:alternativeReview},esc)}${o.options.map((x,i)=>`<section class="card"><h3>Option ${i+1}: ${esc(x.name||'Unnamed possibility')}</h3>${field('Option name or alias',`options.${i}.name`,x.name)}<div class="two">${choose('For gathering',`options.${i}.gatheringId`,x.gatheringId,o.gatherings.map(g=>[g.id,g.title||'Unnamed gathering']))}${choose('Option type',`options.${i}.kind`,x.kind,[['venue','Venue'],['supplier','Supplier']])}</div>${area('Requirements to check (one per line; no sensitive personal details)',`options.${i}.requirements`,x.requirements)}<div class="two">${choose('Price evidence',`options.${i}.priceBasis`,x.priceBasis,[['unknown','Unknown — leave amount empty'],['estimate','Estimate — not a quote'],['quoted','Quote recorded by organiser']])}${field('Amount (one consistent currency; blank if unknown)',`options.${i}.amount`,x.amount,'number')}</div><div class="two">${choose('Availability / confirmation status',`options.${i}.status`,x.status,[['researching','Researching — not confirmed'],['awaiting','Awaiting reply — not confirmed'],['organiser-confirmed','Organiser says confirmed (date required)'],['not-available','Recorded unavailable']])}${field('Date checked (required for organiser confirmation)',`options.${i}.checkedOn`,x.checkedOn,'date')}</div>${area('Private comparison notes — inclusions, exclusions, uncertainties',`options.${i}.notes`,x.notes)}<p class="small">Recording a status does not contact anyone or bind a supplier. Verify terms and availability separately; do not enter account/payment details.</p>${renderResponses(o,x,{optionId:responseOptionId,review:responseReview,draft:responseDraft},esc)}</section>`).join('')}<section class="card"><h3>Compare by gathering</h3><p>This summary updates as you edit. Unlinked alternatives are excluded from the budget. Each explicit link counts at most once; existing manual costs may still overlap—check before linking.</p><button id="option-review">Refresh comparison summary</button><div id="comparison-summary">${comparisonSummary(o)}</div>${optionDecision(o)}<p class="small">Private organiser comparison only. No booking, payment, delivery or automatic selection. Budget links are planning choices, not commitments. Save explicitly if local remembering is enabled.</p></section>`;}

function comparisonSummary(o){return `${o.gatherings.map(g=>`<h3>${esc(g.title||'Unnamed gathering')}</h3>${o.options.filter(x=>x.gatheringId===g.id).length?`<ul>${o.options.filter(x=>x.gatheringId===g.id).map(x=>`<li class="preserve"><strong>${esc(x.name||'Unnamed possibility')} · ${esc(x.kind)}</strong><br>${optionPrice(x)}<br>${optionStatus(x)}<br>Requirements: ${esc(x.requirements||'Not recorded')}<br>Private notes: ${esc(x.notes||'None')}<br>${optionLinkControl(o,x)}</li>`).join('')}</ul>`:'<p>No options recorded.</p>'}`).join('')}`;}

function optionLinkControl(o,x){const l=o.optionLinks.find(l=>l.optionId===x.id);return l?`<span>${optionLinkCurrent(o,l)?'Linked once to budget':'STALE link — excluded from budget'}</span><div class="actions"><button data-option-unlink="${esc(x.id)}">Remove budget link for ${esc(x.name||'unnamed option')}</button></div>`:`<div class="actions"><button data-option-review="${esc(x.id)}">Review budget link for ${esc(x.name||'unnamed option')}</button></div>`;}
function linkedBudget(o){return `<div id="linked-budget"><p class="small">Manual cost rows below and explicit option links are separate. Check for overlapping manual entries before linking. Changing an option or its gathering date, time, place or quantities makes its link stale and excluded until removed and reviewed again. Response-backed links require fresh scope evidence.</p><ul>${o.optionLinks.map(l=>{const x=o.options.find(x=>x.id===l.optionId),stale=!optionLinkCurrent(o,l);const response=(o.responses||[]).filter(r=>r.input.optionId===l.optionId).at(-1),expiry=response?.input.expiry,expired=expiry&&expiry<new Date().toISOString().slice(0,10);return `<li>${esc(x?.name||'Missing option')}${expired?' — RECORDED QUOTE EXPIRED: planning total only; obtain current terms':''} — ${stale?'STALE: excluded':x.amount===''?'Linked: amount unknown (incomplete)':`Linked ${esc(x.amount)} · ${esc(x.priceBasis)}`} · not a booking</li>`;}).join('')}</ul></div>`;}
function optionDecision(o){if(!optionReview)return '';if(optionReview.occasionId!==o.id||!o.options.some(x=>x.id===optionReview.optionId&&JSON.stringify(x)===optionReview.source)){optionReview=null;return ''; }const x=o.options.find(x=>x.id===optionReview.optionId),g=o.gatherings.find(g=>g.id===x.gatheringId),currency=responseCurrency(o,x.id);return `<section id="option-decision" class="card actions"><h3 id="option-decision-heading" tabindex="-1">Review this exact budget decision</h3><p><strong>${esc(x.name||'Unnamed option')}</strong> · ${esc(x.kind)} · ${esc(g?.title||'Gathering')}</p><p>${optionPrice(x)}<br>${optionStatus(x)}</p><p>${x.amount===''?'The price is unknown. Linking will keep the budget incomplete, not add zero.':'This amount will be counted once alongside manual cost rows.'} Check existing manual rows and other linked alternatives for overlap. A quote/estimate is not a payment or booking. This does not confirm availability, contact anyone, choose the venue or create a supplier commitment.</p>${currency?`<p><strong>Recorded response currency: ${esc(currency)}.</strong> The budget has no currency model or conversion. Verify every manual cost and linked amount uses this currency. Mixed known response currencies are blocked. A manually changed option may no longer match the original quote—review the response history.</p><label class="check"><input type="checkbox" id="budget-currency-ack">I checked that ${esc(currency)} matches all amounts in this budget.</label>`:''}<button id="option-link" class="primary" ${currency?'disabled':''}>Link this exact option to budget</button> <button id="option-cancel">Cancel budget decision</button></section>`;}

backupUI=mountBackup(document.querySelector('#backup-panel'),{
 getData:()=>({occasions,active}),getGeneration:()=>[editVersion,view,active],isBusy:()=>retentionBusy,
 replaceSession:data=>{
  guestReview=null;helperReview=null;optionReview=null;journeyProposal=null;requestDraft=null;evidenceReview=null;enquiryPacket=null;enquiryFileReview=null;responseOptionId=null;responseReview=null;responseDraft=null;
  alternativeSelection=null;alternativeReview=null;manualDraft=null;manualPackageId=null;moneyEditor=null;moneyReview=null;quantityDrafts.clear();occasions=structuredClone(data.occasions);active=data.active;serial=1;editVersion++;dirty=true;remember=false;expectedRevision=null;pending=null;
  try{pending=retention?.inspect()??null;}catch(error){retentionMessage=error.message;}
  view='edit';render();focusHeading();retentionMessage='Imported backup is session-only. Existing browser storage was not changed. Remember is OFF.';retentionRender();
 }
});

removalUI=mountRemoval(document.querySelector('#removal-panel'),document.querySelector('#panel'),{getOccasion:current,isBusy:()=>retentionBusy,esc,message,replaceOccasion:next=>{occasions=occasions.map(o=>o.id===next.id?next:o);mark();render();}});

async function loadDirectory(){const ticket=++directoryTicket;directoryLoading=true;directoryError='';directoryReview=null;if(view==='directory')render();try{if(!directoryData){const parsed=await fetchDirectory();if(ticket!==directoryTicket)return;directoryData=parsed;}}catch(error){if(ticket===directoryTicket){directoryData=null;directoryError='Directory unavailable or invalid. No results were invented and your plan is unchanged. You can retry or use manual-source tools.';}}finally{if(ticket===directoryTicket){directoryLoading=false;if(view==='directory'){render();focusHeading();}}}}
